// ── Tests ──────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use once_cell::sync::Lazy;
    use sea_query::Value;
    use std::time::Duration;
    use tokio::sync::Mutex as AsyncMutex;

    static TEST_MUTEX: Lazy<AsyncMutex<()>> = Lazy::new(|| AsyncMutex::new(()));

    fn sqlite_settings() -> PoolSettings {
        PoolSettings {
            max_connections: Some(1),
            min_connections: Some(1),
            acquire_timeout: Some(Duration::from_secs(5)),
            ..PoolSettings::default()
        }
    }

    /// Decode msgpack columnar result [columns, rows] → (columns, rows).
    /// Each row is a Vec of rmpv::Value.
    fn decode_columnar(buf: &[u8]) -> (Vec<String>, Vec<Vec<rmpv::Value>>) {
        let val: rmpv::Value = rmp_serde::from_slice(buf).unwrap();
        let arr = val.as_array().unwrap();
        let columns: Vec<String> = arr[0]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect();
        let rows: Vec<Vec<rmpv::Value>> = arr[1]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row.as_array().unwrap().clone())
            .collect();
        (columns, rows)
    }

    #[tokio::test]
    async fn init_and_close_multiple_pools() {
        let _guard = TEST_MUTEX.lock().await;
        close_all_pools().await.unwrap();

        init_pool("default", "sqlite::memory:", sqlite_settings())
            .await
            .unwrap();
        init_pool("analytics", "sqlite::memory:", sqlite_settings())
            .await
            .unwrap();

        execute_statement("default", "CREATE TABLE foo (id INTEGER)", &[])
            .await
            .unwrap();
        execute_statement("analytics", "CREATE TABLE bar (id INTEGER)", &[])
            .await
            .unwrap();

        assert!(matches!(
            init_pool("default", "sqlite::memory:", sqlite_settings()).await,
            Err(DriverError::PoolAlreadyExists(_))
        ));

        close_pool("default").await.unwrap();
        close_pool("analytics").await.unwrap();

        assert!(matches!(
            close_pool("default").await,
            Err(DriverError::PoolNotFound(_))
        ));
    }

    #[tokio::test]
    async fn execute_with_parameters_sqlite() {
        let _guard = TEST_MUTEX.lock().await;
        close_all_pools().await.unwrap();

        init_pool("default", "sqlite::memory:", sqlite_settings())
            .await
            .unwrap();

        execute_statement(
            "default",
            "CREATE TABLE foo (id INTEGER PRIMARY KEY, name TEXT)",
            &[],
        )
        .await
        .unwrap();

        execute_statement(
            "default",
            "INSERT INTO foo (id, name) VALUES (?, ?)",
            &[Value::from(1_i64), Value::from(String::from("Ada"))],
        )
        .await
        .unwrap();

        let (bytes, num_rows) = execute_query_columnar(
            "default",
            "SELECT name FROM foo WHERE id = ?",
            &[Value::from(1_i64)],
            None,
        )
        .await
        .unwrap();

        assert_eq!(num_rows, 1);
        let (columns, rows) = decode_columnar(&bytes);
        assert_eq!(columns, vec!["name"]);
        assert_eq!(rows[0][0].as_str().unwrap(), "Ada");

        close_pool("default").await.unwrap();
    }

    #[tokio::test]
    async fn transaction_commit_sqlite() {
        let _guard = TEST_MUTEX.lock().await;
        close_all_pools().await.unwrap();

        init_pool("default", "sqlite::memory:", sqlite_settings())
            .await
            .unwrap();

        execute_statement(
            "default",
            "CREATE TABLE foo (id INTEGER PRIMARY KEY, name TEXT)",
            &[],
        )
        .await
        .unwrap();

        let tx_id = begin_transaction("default").await.unwrap();
        execute_statement_in_transaction(
            tx_id,
            "INSERT INTO foo (id, name) VALUES (?, ?)",
            &[Value::from(10_i64), Value::from(String::from("Commit"))],
        )
        .await
        .unwrap();
        commit_transaction(tx_id).await.unwrap();

        let (bytes, num_rows) = execute_query_columnar(
            "default",
            "SELECT name FROM foo WHERE id = ?",
            &[Value::from(10_i64)],
            None,
        )
        .await
        .unwrap();
        assert_eq!(num_rows, 1);
        let (_columns, rows) = decode_columnar(&bytes);
        assert_eq!(rows[0][0].as_str().unwrap(), "Commit");

        close_pool("default").await.unwrap();
    }

    #[tokio::test]
    async fn transaction_rollback_sqlite() {
        let _guard = TEST_MUTEX.lock().await;
        close_all_pools().await.unwrap();

        init_pool("default", "sqlite::memory:", sqlite_settings())
            .await
            .unwrap();

        execute_statement(
            "default",
            "CREATE TABLE foo (id INTEGER PRIMARY KEY, name TEXT)",
            &[],
        )
        .await
        .unwrap();

        let tx_id = begin_transaction("default").await.unwrap();
        execute_statement_in_transaction(
            tx_id,
            "INSERT INTO foo (id, name) VALUES (?, ?)",
            &[Value::from(11_i64), Value::from(String::from("Rollback"))],
        )
        .await
        .unwrap();
        rollback_transaction(tx_id).await.unwrap();

        let (_bytes, num_rows) = execute_query_columnar(
            "default",
            "SELECT name FROM foo WHERE id = ?",
            &[Value::from(11_i64)],
            None,
        )
        .await
        .unwrap();
        assert_eq!(num_rows, 0);

        close_pool("default").await.unwrap();
    }

    /// Constraint violations classify via sqlx ErrorKind — never via
    /// message-text matching.
    #[tokio::test]
    async fn unique_violation_is_classified() {
        let _guard = TEST_MUTEX.lock().await;
        close_all_pools().await.unwrap();

        init_pool("default", "sqlite::memory:", sqlite_settings())
            .await
            .unwrap();

        execute_statement(
            "default",
            "CREATE TABLE foo (id INTEGER PRIMARY KEY, email TEXT UNIQUE)",
            &[],
        )
        .await
        .unwrap();

        execute_statement(
            "default",
            "INSERT INTO foo (email) VALUES (?)",
            &[Value::from(String::from("a@b.c"))],
        )
        .await
        .unwrap();

        let err = execute_statement(
            "default",
            "INSERT INTO foo (email) VALUES (?)",
            &[Value::from(String::from("a@b.c"))],
        )
        .await
        .unwrap_err();

        assert_eq!(err.db_kind(), Some(DbErrorKind::UniqueViolation));
        assert!(err.sqlstate().is_some());

        close_pool("default").await.unwrap();
    }

    /// An abandoned transaction (registry entry dropped without commit or
    /// rollback) must not leak an open transaction into the pooled
    /// connection: sqlx rolls it back on drop. With max_connections=1 the
    /// next query is guaranteed to reuse that same connection.
    #[tokio::test]
    async fn abandoned_transaction_rolls_back_on_drop() {
        let _guard = TEST_MUTEX.lock().await;
        close_all_pools().await.unwrap();

        init_pool("default", "sqlite::memory:", sqlite_settings())
            .await
            .unwrap();

        execute_statement(
            "default",
            "CREATE TABLE foo (id INTEGER PRIMARY KEY, name TEXT)",
            &[],
        )
        .await
        .unwrap();

        let tx_id = begin_transaction("default").await.unwrap();
        execute_statement_in_transaction(
            tx_id,
            "INSERT INTO foo (id, name) VALUES (?, ?)",
            &[Value::from(1_i64), Value::from(String::from("Ghost"))],
        )
        .await
        .unwrap();

        let abandoned = transaction_registry().remove(tx_id).await.unwrap();
        drop(abandoned);

        // Uncommitted insert must be gone and the connection usable.
        let (_bytes, num_rows) = execute_query_columnar(
            "default",
            "SELECT name FROM foo WHERE id = ?",
            &[Value::from(1_i64)],
            None,
        )
        .await
        .unwrap();
        assert_eq!(num_rows, 0);

        execute_statement(
            "default",
            "INSERT INTO foo (id, name) VALUES (?, ?)",
            &[Value::from(2_i64), Value::from(String::from("Alive"))],
        )
        .await
        .unwrap();

        close_pool("default").await.unwrap();
    }
}
